INTRO = 'Cindy calls Seung-chan into a quiet stairwell to remind him she joined the show because of his invitation and demands his loyalty, receiving unexpectedly sincere advice in return. Listen for "inneun geudaero", meaning just as you are.'
STORY = [('cindy', '저 이 프로그램 피디님 때문에 하는 거예요, 아시죠?', 'I am doing this program because of you, producer, you know that, right?', [(603, '이 프로그램'), (603, '때문에 하는 거예요'), (604, '아시죠')], ''), ('cindy', '나한테 제안했잖아요, 같이 하자고.', 'You were the one who proposed that we do it together.', [(605, '나한테 제안했잖아요'), (605, '하자고')], ''), ('seungchan', '네, 물론입니다. 제안 받아들여 주셔서 정말 감사합니다.', 'Yes, of course. I am truly grateful that you accepted the offer.', [(606, '네, 물론입니다'), (607, '제안 받아들여 주신 거 정말 감사하게')], ''), ('cindy', '그러니까 저한테 잘하셔야 돼요. 철저히 제 편, 아시겠죠?', 'So you have to treat me well. Strictly on my side, got it?', [(608, '그러니까 저한테 잘하셔야 돼요'), (617, '철저히 제 편'), (618, '아시겠죠')], ''), ('cindy', '지난번에 어묵탕이랑 멸치김밥 잘 먹었어요.', 'Last time, I really enjoyed the fish-cake soup and anchovy rice rolls.', [(620, '지난번에 어묵탕이랑 멸치김밥'), (621, '잘 먹었어요')], ''), ('cindy', '아시겠지만 저 예능 처음이라 뭘 어떻게 해야 되는지 잘 몰라요.', "As you know, it is my first variety show, so I don't know what to do.", [(626, '아시겠지만 저 예능 처음이라 잘 몰라요. 뭘 어떻게 해야 되는지')], ''), ('seungchan', '뭘 어떻게 해야 할지 모르겠으면 아무것도 안 하면 돼요.', "If you don't know what to do, you don't have to do anything at all.", [(628, '뭘 어떻게 해야 할지 모르겠으면 아무것도 안 하면 돼요')], ''), ('seungchan', '이건 리얼 버라이어티거든요.', 'Because this is a reality variety show.', [(629, '이건 리얼 버라이어티거든요')], ''), ('seungchan', '어렵게 생각하면 한없이 어렵지만 쉽게 생각하면 별거 아니에요.', 'If you overthink it, it is endlessly hard, but if you think of it simply, it is nothing big.', [(630, '어렵게 생각하면 한없이 어렵지만 쉽게 생각하면 별거 아닌 게')], ''), ('seungchan', '뭘 하려고 그러지 말고 그냥 있는 그대로 보여 주면 되거든요.', "Don't try to put anything on, just show yourself as you really are.", [(631, '뭘 하려고 그러지 말고 그냥 있는 그대로 보여주면 되거든')], ''), ('cindy', '있는 그대로, 내 모습 그대로? 알겠어요.', 'Just as I am, my true self? Got it.', [(632, '있는 그대로'), (634, '내 모습 그대로'), (635, '알겠어요')], ''), ('cindy', '아무튼 저 촬영장에서도 피디님만 보고 가요. 수고하세요.', 'Anyway, I am going to the set counting only on you. Keep up the good work.', [(637, '저 촬영장에서도'), (637, '보고 가요'), (638, '수고하세요')], '')]
OPENER = "Now let's go through it line by line with the English translation."
